-- Accesso limitato per gli agenti Claude: possono solo leggere id/stato/link, aggiungere annunci nuovi,
-- segnare come spariti quelli non ancora contattati e scrivere il registro. Il token sta in agent_tokens.
create table if not exists public.agent_tokens (token text primary key, nome text);
alter table public.agent_tokens enable row level security;
create or replace function public.agent_ok(p_token text) returns boolean language sql stable security definer set search_path = public as $$ select exists (select 1 from agent_tokens where token = p_token) $$;
create or replace function public.agent_elenco(p_token text) returns table (id text, stato text, link text) language plpgsql stable security definer set search_path = public as $$ begin if not agent_ok(p_token) then raise exception 'token non valido'; end if; return query select a.id, a.d->>'stato', a.d->>'link' from annunci a; end $$;
create or replace function public.agent_aggiungi(p_token text, p_righe jsonb) returns integer language plpgsql security definer set search_path = public as $$ declare n integer; begin if not agent_ok(p_token) then raise exception 'token non valido'; end if; insert into annunci (id, d) select r->>'id', r->'d' from jsonb_array_elements(p_righe) r where r->>'id' is not null on conflict (id) do nothing; get diagnostics n = row_count; return n; end $$;
create or replace function public.agent_sparito(p_token text, p_id text, p_motivo text) returns boolean language plpgsql security definer set search_path = public as $$ begin if not agent_ok(p_token) then raise exception 'token non valido'; end if; update annunci set d = d || jsonb_build_object('stato', 'Non più disponibile', 'motivo', p_motivo), aggiornato = now() where id = p_id and d->>'stato' in ('Da aprire', 'Da contattare'); return found; end $$;
create or replace function public.agent_registro(p_token text, p_d jsonb) returns void language plpgsql security definer set search_path = public as $$ begin if not agent_ok(p_token) then raise exception 'token non valido'; end if; insert into controlli (id, d) values ('ultimo', p_d) on conflict (id) do update set d = excluded.d; insert into controlli (id, d) values ('giro-' || to_char(now() at time zone 'Europe/Zurich', 'YYYYMMDD-HH24MI') || '-' || coalesce(p_d->>'agente', 'agente'), p_d) on conflict (id) do nothing; end $$;
revoke all on function public.agent_ok(text) from public, anon, authenticated;
grant execute on function public.agent_elenco(text), public.agent_aggiungi(text, jsonb), public.agent_sparito(text, text, text), public.agent_registro(text, jsonb) to anon, authenticated, service_role;
